    userStore.projectName ||
    "—"
  );
});

const ensureProjectInfo = async () => {
  if (userStore.project && userStore.projectName) {
    return;
  }
  if (!userStore.token) {
    return;
  }
  try {
    const houseResponse = await getMyHouseList({
      identityType: 1,
      identityStatus: 2,
    });
    const houseList = houseResponse.data || [];
    userStore.setHouse(houseList);

    if (userStore.project) {
      const house = houseList.find(
        (item) => String(item.complexId) === String(userStore.project)
      );
      if (house) {
        applyHouseSelection(house);
        return;
      }
      const projectResponse = await listComplexCommunitySubdistrictByToken();
      const projectList =
        projectResponse.code === 200 ? projectResponse.data || [] : [];
      const project = projectList.find(
        (item) => String(item.complexId) === String(userStore.project)
      );
      if (project) {
        applyProjectSelection(project, houseList);
      }
      return;
    }
    if (houseList[0]) {
      applyHouseSelection(houseList[0]);
    }
  } catch {
    // ignore
  }
};

const loadAssetData = async () => {
  if (!userStore.project) {
    info.value = defaultInfo();
    standards.value = [];
    return;
  }
  const projectId = userStore.project;
  getInfoByCodeProjectAssetInfo(projectId).then((res) => {
    info.value = { ...defaultInfo(), ...(res.data || {}) };
  });
  getInfoByCodeChargeStandard(projectId).then((res) => {
    standards.value = res.data || [];
  });
};

onShow(async () => {
  getDict("benefit_pay_type").then((res) => {
    paymentMethodOptions.value = res;
  });
  await ensureProjectInfo();
  await loadAssetData();
